// panel.tsx
+'use client';
+import { useState } from 'react';
+import { ServerReport } from './server-report';   // reads from the DB
+
+export function Panel({ title, onExpand }: {
+  title: string;
+  onExpand: () => void;          // passed from a Server Component
+}) {
+  const [open, setOpen] = useState(false);
+  return (
+    <section>
+      <button onClick={() => { setOpen(true); onExpand(); }}>{title}</button>
+      {open && <ServerReport />}
+    </section>
+  );
+}

